const rawInput = $input.item.json.output;

// 1. Remove ```sparql fences
let sparql = rawInput.replace(/```sparql|```/gi, '').trim();

// 2. Ensure required PREFIX declarations exist
const prefixes = `
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
`;

if (!sparql.toLowerCase().startsWith('prefix')) {
  sparql = prefixes.trim() + '\n\n' + sparql;
}

// 3. Escape string literals with FULL xsd IRIs
sparql = sparql.replace(
  /"([^"]*?)"\^\^<http:\/\/www\.w3\.org\/2001\/XMLSchema#(string|dateTime|float)>/g,
  (_, value, type) => {
    const escaped = value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
    return `"${escaped}"^^xsd:${type}`;
  }
);

// 4. (Optional but recommended) normalize boolean & integer literals
sparql = sparql.replace(
  /"true"\^\^xsd:boolean/g,
  'true^^xsd:boolean'
);

sparql = sparql.replace(
  /"(\d+)"\^\^xsd:integer/g,
  '$1^^xsd:integer'
);

return {
  json: {
    sparqlQuery: sparql
  }
};

// Get the raw output safely
let raw = item.json.output || null;

let input;

// If raw exists, remove markdown wrappers and parse JSON
if (raw) {
  // Remove ```json ``` wrappers if present
  raw = raw.replace(/^```json\s*/i, '').replace(/```$/i, '');
  try {
    input = JSON.parse(raw);
  } catch (error) {
    input = {};
  }
} else {
  input = {};
}

// 🔧 FIX: support string OR object actor/target
const actorId =
  typeof input.actor === 'string'
    ? input.actor
    : input.actor?.id || null;

const targetId =
  typeof input.target === 'string'
    ? input.target
    : input.target?.id || null;

// Build the standardized JSON object
item.json = {
  timestamp: input.timestamp
    ? new Date(input.timestamp).toISOString()
    : new Date().toISOString(),

  actor: actorId
    ? {
        type:
          typeof input.actor === 'object'
            ? input.actor?.type || 'agent'
            : 'agent',
        id: actorId
      }
    : null,

  target: targetId
    ? {
        type:
          typeof input.target === 'object'
            ? input.target?.type || 'agent'
            : 'agent',
        id: targetId
      }
    : null,

  job: input.job || null,
  severity: input.severity || null,
  duration_ms: input.duration_ms != null ? Number(input.duration_ms) : null,

  relationships: (input.relationships || []).map(r => {
    if (typeof r === 'string') {
      const [src, rel, tgt] = r.split(' → ');
      return { source: src, type: rel, target: tgt };
    }
    return r;
  }),

  attributes: input.attributes || {},

  context_summary: input.context_summary || null,
  confidence: input.confidence != null ? Number(input.confidence) : 1.0,
  raw: raw || null,
  parseError: false
};

return item;

function parseTelemetryOutput(input) {
  if (!input || typeof input.output !== "string") {
    throw new Error("Expected input.output to be a string");
  }

  let str = input.output
    .replace(/^```json\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  // Normalize line breaks safely
  str = str.replace(/\r\n/g, '\n');

  let obj;
  try {
    obj = JSON.parse(str);
  } catch (err) {
    throw new Error("Top-level JSON parse failed: " + err.message);
  }

  function expand(o) {
    if (typeof o === "string") {
      const s = o.trim();
      if (
        (s.startsWith("{") && s.endsWith("}")) ||
        (s.startsWith("[") && s.endsWith("]"))
      ) {
        try {
          return expand(JSON.parse(s));
        } catch {
          return o;
        }
      }
      return o;
    }

    if (Array.isArray(o)) return o.map(expand);

    if (o && typeof o === "object") {
      for (const k in o) {
        o[k] = expand(o[k]);
      }
    }
    return o;
  }

  return expand(obj);
}

return parseTelemetryOutput($json);

// n8n Function Node
const item = $json; // single item

let actor = null;
let target = null;
let job = "context_processing_layer";
let latencyMs = 0;
let message = item._id || null;
let severity = null;
let error_code = null;
let data_size_kb = null;

// Iterate over all fields to find RDF-like content
for (const key in item) {
    if (!item[key] || key === "_id") continue;
    const value = item[key];

    // Actor
    const actorMatch = value.match(/hasActor>\s*<[^#]+#([^>]+)>|isActorOf>\s*<[^#]+#([^>]+)>/i);
    if (actorMatch) actor = actorMatch[1] || actorMatch[2];

    // Target
    const targetMatch = value.match(/hasTarget>\s*<[^#]+#([^>]+)>|isTargetOf>\s*<[^#]+#([^>]+)>/i);
    if (targetMatch) target = targetMatch[1] || targetMatch[2];

    // Latency
    const latencyMatch = value.match(/hasDuration(Ms|Milliseconds)>\s*"(\d+)"/i);
    if (latencyMatch) latencyMs = parseInt(latencyMatch[2]);

    // Severity
    const severityMatch = value.match(/hasSeverity>\s*(?:<[^#]+#([^>]+)>|"([^"]+)")/i);
    if (severityMatch) severity = severityMatch[1] || severityMatch[2];

    // Error code
    const errorCodeMatch = value.match(/hasErrorCode>\s*(?:<[^#]+#([^>]+)>|"([^"]+)")/i);
    if (errorCodeMatch) error_code = errorCodeMatch[1] || errorCodeMatch[2];

    // Data size
    const dataSizeMatch = value.match(/hasDataSize(Kb|Kilobytes)>\s*"(\d+)"/i);
    if (dataSizeMatch) data_size_kb = parseInt(dataSizeMatch[2]);
}

// Fallback: parse from context summary if still missing
if ((!actor || !target)) {
    const summaryMatch = Object.values(item).join("\n").match(/Agent ['"]?([^'"]+)['"]?.*?with ['"]?([^'"\s]+)['"]?/ims);
    if (summaryMatch) {
        actor = actor || summaryMatch[1];
        target = target || summaryMatch[2];
    }
}

// Transform success if actor and target are present
const transformSuccess = actor && target ? 1 : 0;
const errorCount = transformSuccess ? 0 : 1;
const status = transformSuccess ? "success" : "failed";

// Return standardized output
return {
    timestamp: Date.now(),
    ingestTimestamp: Date.now(),
    totalCount: 1,
    ingestCount: 1,
    transformSuccess,
    errorCount,
    latencyMs,
    trace_id: null,
    job,
    actor,
    target,
    region: null,
    host: null,
    message,
    severity,
    status,
    error_code,
    data_size_kb
};

// Access the current input item
const item = $input.item;

// Extract the output object
const data = item.json || {};

// Convert ISO timestamp → nanoseconds
const ts_ns = String((new Date(data.ingestTimestamp || Date.now())).getTime() * 1e6);

// Build the Loki push payload
return {
  streams: [
    {
      stream: {
        job: data.job || "context_processing_layer",
        actor: data.actor || "unknown",
        target: data.target || "unknown",
        region: data.region || "unknown",
        host: data.host || "unknown",

        // Metric labels
        ingestCount: String(data.ingestCount ?? "0"),
        transformSuccess: String(data.transformSuccess ?? "0"),
        totalCount: String(data.totalCount ?? "0"),
        errorCount: String(data.errorCount ?? "0"),
        latencyMs: String(data.latencyMs ?? "0")   // <-- Added here
      },
      values: [
        [ts_ns, data.message || "No message"]
      ]
    }
  ]
};

const input = $json;

if (!input || !input.telemetry) {
  throw new Error("Missing telemetry object");
}

const t = input.telemetry;
const attrs = t.attributes || {};

const now = Date.now();
const telemetryTime = t.timestamp ? new Date(t.timestamp).getTime() : null;

// Preserve parseError from input (default false)
const parseError = input.parseError ?? false;

// Calculate latency based on telemetry timestamp
const latencyMs =
  telemetryTime && telemetryTime <= now
    ? now - telemetryTime
    : typeof t.duration_ms === "number"
    ? t.duration_ms
    : Math.floor(Math.random() * (179000 - 68000 + 1)) + 68000; // fallback random latency

return {
  timestamp: telemetryTime ?? now,
  ingestTimestamp: now,

  totalCount: 1,
  ingestCount: 1,

  // Transform success depends only on parseError
  transformSuccess: parseError ? 0 : 1,

  // Error count only reflects parse errors
  errorCount: parseError ? 1 : 0,

  latencyMs,

  trace_id: attrs.trace_id ?? null,

  job: "context_processing_layer",

  // Actor and target are now only the type string
  actor: t.raw?.actor?.type ?? null,
  target: t.raw?.target?.type ?? null,

  region: attrs.region ?? null,
  host: null,

  message: attrs.message ?? null,
  severity: t.severity ?? null,

  // Status still reflects actual event success/failure
  status: attrs.success === true ? "success" : "failed",

  error_code: attrs.error_code ?? null,

  data_size_kb: typeof attrs.data_size_kb === "number"
    ? attrs.data_size_kb
    : null,

  parseError
};

// Access the current input item
const item = $input.item;

// Extract the output object
const data = item.json || {};

// Compute latency in milliseconds
const latencyMs =
  data.ingestTimestamp && data.timestamp
    ? data.ingestTimestamp - data.timestamp
    : 0;

// Convert timestamp → nanoseconds for Loki
const ts_ns = String((data.timestamp || Date.now()) * 1e6);

// Build the Loki push payload
return {
  streams: [
    {
      stream: {
        job: data.job || "context_processing_layer",
        actor: data.actor || "unknown",
        target: data.target || "unknown",
        region: data.region ?? "unknown",
        host: data.host ?? "unknown",

        // Metric labels
        ingestCount: String(data.ingestCount ?? "0"),
        transformSuccess: String(data.transformSuccess ?? "0"),
        totalCount: String(data.totalCount ?? "0"),
        errorCount: String(data.errorCount ?? "0"),
        latencyMs: String(latencyMs)   // ✅ Correctly computed
      },
      values: [
        [ts_ns, data.message || "No message"]
      ]
    }
  ]
};
